    uint32_t CinW = static_cast<uint32_t>(w_shape->GetDim(0));
    uint32_t Cout = static_cast<uint32_t>(w_shape->GetDim(1));
    uint32_t K    = static_cast<uint32_t>(w_shape->GetDim(2));

    if (Cin != CinW) {
        return ge::GRAPH_FAILED;
    }

    // 获取属性
    int64_t stride_attr = 1;
    int64_t padding_attr = 0;
    int64_t dilation_attr = 1;
    auto stride_ptr = context->GetAttr("stride");
    if (stride_ptr != nullptr) { stride_attr = stride_ptr->GetInt(); }
    auto padding_ptr = context->GetAttr("padding");
    if (padding_ptr != nullptr) { padding_attr = padding_ptr->GetInt(); }
    auto dilation_ptr = context->GetAttr("dilation");
