                      + 1u;
    uint32_t Lout = static_cast<uint32_t>(Lout64);

    // 简单按输出长度做分块
    const uint32_t kMinTile = 4096;
    uint32_t tileOutLen = (Lout < kMinTile) ? Lout : kMinTile;
    uint32_t tileNum = CeilDiv(Lout, tileOutLen);

    context->SetBlockDim(BLOCK_DIM);

    tiling.set_N(N);
    tiling.set_Cin(Cin);
    tiling.set_Cout(Cout);
    tiling.set_Lin(Lin);
    tiling.set_Lout(Lout);
    tiling.set_K(K);
    tiling.set_stride(stride);
    tiling.set_padding(padding);
    tiling.set_dilation(dilation);
    tiling.set_tileOutLen(tileOutLen);
