at::Tensor conv_transposed_1d_asymmetric_input_square_kernel_padded_strided_dilated_custom_impl_npu(
    const at::Tensor& x, const at::Tensor& w, int64_t stride, int64_t padding, int64_t dilation) {

    TORCH_CHECK(x.dim() == 3, \"x must be 3D [N, Cin, Lin]\");
    TORCH_CHECK(w.dim() == 3, \"w must be 3D [Cin, Cout, K]\");
    TORCH_CHECK(x.scalar_type() == at::kFloat, \"dtype must be float32\");
    TORCH_CHECK(w.scalar_type() == at::kFloat, \"dtype must be float32\");
    TORCH_CHECK(x.device().is_privateuseone(), \"x must be on NPU\");
    TORCH_CHECK(w.device().is_privateuseone(), \"w must be on NPU\");

    int64_t N = x.size(0);
    int64_t Cin = x.size(1);
    int64_t Lin = x.size(2);
    int64_t CinW = w.size(0);
    int64_t Cout = w.size(1);
    int64_t K = w.size(2);

    TORCH_CHECK(Cin == CinW, \"input Cin must match weight Cin\");

    int64_t Lout = conv_transpose1d_out_len(Lin, stride, padding, dilation, K);

    at::Tensor z = at::empty({N, Cout, Lout}, x.options());

